before:
describe("login", () => {
  it("rejects a bad password", () => {
    expect(login("a", "b")).toBe(false);
  });
  it("accepts a good password", () => {
    expect(login("a", "right")).toBe(true);
  });
});

after:
describe("login", () => {
  it("rejects a bad password", () => {
    expect(login("a", "b")).toBe(false);
  });
  it.only("accepts a good password", () => {
    expect(login("a", "right")).toBe(true);
  });
});
